INSERT INTO `pages` (`id`, `title`, `slug`, `content`, `excerpt`, `meta_title`, `meta_description`, `meta_keywords`, `og_image`, `featured_image`, `show_title`, `show_excerpt`, `center_title`, `show_breadcrumbs`, `show_featured_image`, `show_sidebar`, `sidebar_position`, `container_width`, `status`, `published_at`, `password`, `parent_id`, `sort_order`, `is_system`, `created_by`, `created_at`, `updated_at`, `deleted_at`) VALUES (1,'Privacy Policy','privacy-policy','<h2>1. Information We Collect</h2><p>We collect information you provide directly to us, such as when you create or modify your account, request support, or otherwise communicate with us.</p><h2>2. How We Use Your Information</h2><p>We may use the information we collect to provide, maintain, and improve our services, and to develop new tools and features.</p><h2>3. Data Security</h2><p>We use reasonable measures to help protect information about you from loss, theft, misuse, and unauthorized access.</p>','Our commitment to protecting your personal data and privacy.',NULL,NULL,NULL,NULL,NULL,1,0,0,1,0,0,'left','default','published','2026-07-23 19:08:37',NULL,NULL,0,1,NULL,'2026-07-23 19:08:37','2026-07-23 19:08:37',NULL),(2,'Terms of Service','terms-of-service','<h2>1. Acceptance of Terms</h2><p>By accessing or using our services, you agree to be bound by these terms.</p><h2>2. Use of Services</h2><p>You may use our services only as permitted by law and these terms.</p><h2>3. Limitation of Liability</h2><p>To the maximum extent permitted by law, MakeAI shall not be liable for any indirect, incidental, special, or consequential damages.</p>','The legal agreement between you and MakeAI for using our services.',NULL,NULL,NULL,NULL,NULL,1,0,0,1,0,0,'left','default','published','2026-07-23 19:08:37',NULL,NULL,0,1,NULL,'2026-07-23 19:08:37','2026-07-23 19:08:37',NULL),(3,'Contact Us','contact','<h2>We\'re Here to Help</h2><p>Have a question about our features, pricing, or anything else? Our team is ready to answer all your questions.</p>','Get in touch with the MakeAI support team.',NULL,NULL,NULL,NULL,NULL,1,0,0,1,0,0,'left','default','published','2026-07-23 19:08:37',NULL,NULL,0,1,NULL,'2026-07-23 19:08:37','2026-07-23 19:08:37',NULL),(4,'About Us','about','<h2>Empowering Creativity with AI</h2><p>MakeAI is at the forefront of the generative AI revolution. We provide tools that help creators, developers, and businesses unlock their full potential using the power of artificial intelligence.</p><h2>Our Mission</h2><p>To democratize access to advanced AI technology and enable everyone to create high-quality content effortlessly.</p>','Discover the story behind MakeAI and our mission to empower creators.',NULL,NULL,NULL,NULL,NULL,1,0,0,1,0,0,'left','default','published','2026-07-23 19:08:37',NULL,NULL,0,1,NULL,'2026-07-23 19:08:37','2026-07-23 19:08:37',NULL),(5,'Frequently Asked Questions','faq','<h3>What is MakeAI?</h3><p>MakeAI is an all-in-one platform for generative AI, offering tools for text generation, image creation, and more.</p><h3>Is there a free trial?</h3><p>Yes, we offer a free plan with limited credits to help you get started.</p><h3>How do I cancel my subscription?</h3><p>You can cancel your subscription at any time from your account settings.</p>','Find answers to the most common questions about MakeAI.',NULL,NULL,NULL,NULL,NULL,1,0,0,1,0,0,'left','default','published','2026-07-23 19:08:37',NULL,NULL,0,1,NULL,'2026-07-23 19:08:37','2026-07-23 19:08:37',NULL),(6,'Cookie Policy','cookie-policy','<h2>What are Cookies?</h2><p>Cookies are small text files that are stored on your device when you visit a website.</p><h2>How We Use Cookies</h2><p>We use cookies to understand how you use our site and to improve your experience.</p>','How we use cookies to improve your experience on our platform.',NULL,NULL,NULL,NULL,NULL,1,0,0,1,0,0,'left','default','published','2026-07-23 19:08:37',NULL,NULL,0,1,NULL,'2026-07-23 19:08:37','2026-07-23 19:08:37',NULL);
