INSERT INTO `payment_gateways` (`id`, `slug`, `name`, `description`, `is_enabled`, `is_test_mode`, `processing_fee_type`, `processing_fee_value`, `credentials`, `sort_order`, `created_at`, `updated_at`) VALUES (1,'stripe','Stripe','Cards, wallets, and recurring subscriptions.',0,1,'none',0.00,NULL,1,'2026-07-23 19:08:37','2026-07-23 19:08:37'),(2,'paypal','PayPal','PayPal checkout and subscriptions.',0,1,'none',0.00,NULL,2,'2026-07-23 19:08:37','2026-07-23 19:08:37'),(3,'paddle','Paddle','Merchant of record payments and VAT handling.',0,1,'none',0.00,NULL,3,'2026-07-23 19:08:37','2026-07-23 19:08:37'),(4,'razorpay','Razorpay','Cards, UPI, and India-focused checkout.',0,1,'none',0.00,NULL,4,'2026-07-23 19:08:37','2026-07-23 19:08:37'),(5,'sslcommerz','SSLCommerz','Bangladesh payment gateway.',0,1,'none',0.00,NULL,5,'2026-07-23 19:08:37','2026-07-23 19:08:37'),(6,'coingate','CoinGate','Crypto payments.',0,1,'none',0.00,NULL,6,'2026-07-23 19:08:37','2026-07-23 19:08:37'),(7,'paystack','Paystack','Africa-focused cards and bank payments.',0,1,'none',0.00,NULL,7,'2026-07-23 19:08:37','2026-07-23 19:08:37'),(8,'bank_transfer','Bank Transfer','Manual bank transfer with admin approval.',0,1,'none',0.00,NULL,8,'2026-07-23 19:08:37','2026-07-23 19:08:37'),(9,'2checkout','2Checkout','2Checkout hosted checkout payments.',0,1,'none',0.00,NULL,9,'2026-07-23 19:08:37','2026-07-23 19:08:37');
