INSERT INTO `plans` (`id`, `name`, `slug`, `description`, `bottom_info_text`, `price_monthly`, `price_yearly`, `price_lifetime`, `original_price_monthly`, `original_price_yearly`, `original_price_lifetime`, `vat_percentage`, `trial_all_countries`, `credits`, `features`, `is_featured`, `is_active`, `is_free`, `trial_days`, `sort_order`, `stripe_price_monthly_id`, `stripe_price_yearly_id`, `paypal_plan_monthly_id`, `paypal_plan_yearly_id`, `created_at`, `updated_at`) VALUES (1,'Free','free','Get started with basic AI features',NULL,0.00,0.00,NULL,NULL,NULL,NULL,0.00,0,100.00,'[\"5 AI templates\", \"GPT-4o-mini only\", \"10 chats\", \"Basic support\"]',0,1,1,0,1,NULL,NULL,NULL,NULL,'2026-07-23 19:08:37','2026-07-23 19:08:37'),(2,'Starter','starter','Perfect for individuals and freelancers',NULL,9.99,95.88,NULL,NULL,NULL,NULL,0.00,0,2000.00,'[\"All AI templates\", \"GPT-4o + GPT-4o-mini\", \"50 chats\", \"Priority support\", \"Export content\"]',0,1,0,7,2,NULL,NULL,NULL,NULL,'2026-07-23 19:08:37','2026-07-23 19:08:37'),(3,'Professional','professional','For teams and growing businesses',NULL,29.99,287.88,NULL,NULL,NULL,NULL,0.00,0,10000.00,'[\"All AI templates\", \"All AI models\", \"Unlimited chats\", \"Priority support\", \"API access\", \"Brand voice\", \"Custom templates\"]',1,1,0,14,3,NULL,NULL,NULL,NULL,'2026-07-23 19:08:37','2026-07-23 19:08:37'),(4,'Enterprise','enterprise','Unlimited power for large organizations',NULL,99.99,959.88,4999.00,NULL,NULL,NULL,0.00,0,50000.00,'[\"Everything in Pro\", \"All AI models\", \"Unlimited everything\", \"Dedicated support\", \"Custom integrations\", \"SLA guarantee\", \"White-label ready\"]',0,1,0,0,4,NULL,NULL,NULL,NULL,'2026-07-23 19:08:37','2026-07-23 19:08:37');
